slow_commands.expression:
(() => {
        const element = document.querySelector("[data-scenario-id=\"dialog.loading\"] [data-scenario-dialog-trigger='true']");
        if (!element) return null;
        const rect = element.getBoundingClientRect();
        return {
          x: rect.left + rect.width / 2,
          y: rect.top + rect.height / 2,
          width: rect.width,
          height: rect.height
        };
      })()

(() => {
      const dialog = document.querySelector("[data-scenario-id=\"dialog.loading\"] .jk-dialog[data-jk-component='dialog']");
      return dialog?.open === false &&
        dialog.getAttribute("data-jk-open") === "false";
    })()
